// W4-09a done-when "provenance grep passes" (W4b plan section 11.1 "Labels": greps the set like slice1-synthetic).
// The same pattern denylist as data/provenance.test.ts, over every file of the evaluation directory (case rows,
// renderers, vocabulary, labels, README, manifest) and every generated byte, read as UTF-8 and as Latin-1, and
// inside the decompressed streams of the FlateDecode PDFs and deflated ZIP parts.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { inflateRawSync, inflateSync } from 'node:zlib';
import { PROVENANCE_DENYLIST, scanProvenance } from '../provenance-denylist.js';
import { EVAL_CASES } from './cases.js';
import { EVAL_DIR, generateEvalSet } from './generate.js';

function files(dir: string): string[] {
  return readdirSync(dir).flatMap((entry) => {
    const full = path.join(dir, entry);
    return statSync(full).isDirectory() ? files(full) : [full];
  });
}

/** The decompressed payloads of a document: FlateDecode streams (PDF) and deflated entries (ZIP). */
function inflated(bytes: Buffer): Buffer[] {
  const out: Buffer[] = [];
  const text = bytes.toString('latin1');
  for (const m of text.matchAll(/\/FlateDecode \/Length (\d+) >>\nstream\n/g)) {
    const start = m.index + m[0].length;
    out.push(inflateSync(bytes.subarray(start, start + Number(m[1]))));
  }
  let p = 0;
  while ((p = bytes.indexOf(Buffer.from([0x50, 0x4b, 0x03, 0x04]), p)) >= 0) {
    const method = bytes.readUInt16LE(p + 8);
    const size = bytes.readUInt32LE(p + 18);
    const start = p + 30 + bytes.readUInt16LE(p + 26) + bytes.readUInt16LE(p + 28);
    if (method === 8) out.push(inflateRawSync(bytes.subarray(start, start + size)));
    p = start + size;
  }
  return out;
}

test('the denylist is the slice1-synthetic one (one list, imported by both provenance tests)', () => {
  assert.ok(PROVENANCE_DENYLIST.length >= 12);
  assert.ok(PROVENANCE_DENYLIST.some((r) => r.name === 'the operating company name as a word'));
});

test('no evaluation source file, label, README or manifest matches the provenance denylist', () => {
  const all = files(EVAL_DIR);
  assert.ok(all.some((f) => f.endsWith(path.join('labels', 'ev-dev-01.json'))));
  const hits = all.flatMap((f) => scanProvenance(path.relative(EVAL_DIR, f), readFileSync(f, 'utf8')));
  assert.deepEqual(hits, []);
});

test('no generated document byte sequence matches the denylist (UTF-8, Latin-1 and decompressed streams)', () => {
  let streams = 0;
  const hits = generateEvalSet().flatMap((g) => {
    const id = g.document.documentId;
    const payloads = inflated(g.document.bytes);
    streams += payloads.length;
    return [
      ...scanProvenance(`${id} (utf8)`, g.document.bytes.toString('utf8')),
      ...scanProvenance(`${id} (latin1)`, g.document.bytes.toString('latin1')),
      ...payloads.flatMap((b, i) => scanProvenance(`${id} stream ${i}`, b.toString('utf8'))),
    ];
  });
  assert.deepEqual(hits, []);
  assert.ok(streams > 20, 'the compressed payloads were scanned too');
});

test('filenames, titles and N/A reasons of the case rows match nothing on the denylist', () => {
  const text = EVAL_CASES.flatMap((c) => [
    c.title,
    ...c.slots.flatMap((s) =>
      s.disposition === 'attached'
        ? [s.document.filename]
        : s.disposition === 'not_applicable'
          ? [s.reason]
          : [],
    ),
  ]).join('\n');
  assert.deepEqual(scanProvenance('case rows', text), []);
});
